<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Validation\Rule;use Symfony\Component\HttpFoundation\Response;
class CandidateCvController extends Controller{public function export(Request $request):Response{abort_unless($request->user()->account_type==='candidate',403);$data=$request->validate(['template'=>['required',Rule::in(['classic','modern','minimal','executive','creative','compact'])]]);$profile=$request->user()->candidateProfile;if(!$profile)abort(422,'Completa tu perfil antes de exportar.');$photo=null;if($profile->photo_path&&Storage::disk('local')->exists($profile->photo_path)){$mime=Storage::disk('local')->mimeType($profile->photo_path)?:'image/jpeg';$photo='data:'.$mime.';base64,'.base64_encode(Storage::disk('local')->get($profile->photo_path));}$pdf=Pdf::loadView('pdf.cv.'.$data['template'],['user'=>$request->user(),'profile'=>$profile,'photo'=>$photo])->setPaper('a4');$name='cv-'.str($request->user()->name)->slug().'-empleaterd.pdf';return $pdf->download($name);}}
